"use client"

import * as React from "react"
import { addMinutes, format, startOfDay, type Day, type Locale } from "date-fns"
import { z } from "zod"

import { Button } from "@/components/ui/button"
import { DatePicker } from "@/components/ui/date-picker"
import {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import {
  Form,
  FormBanner,
  FormField,
  FormSubmit,
  useZodForm,
} from "@/components/ui/form"
import { Input } from "@/components/ui/input"
import { SwatchPicker } from "@/components/ui/swatch-picker"
import { Switch } from "@/components/ui/switch"
import { Textarea } from "@/components/ui/textarea"
import { TimeRangeInput } from "@/components/ui/time-input"
import { TimezoneSelect } from "@/components/ui/timezone-select"
import {
  TONES,
  type EventTone,
  type ScheduleEvent,
  type ScheduleStrings,
} from "./schedule-utils"

const TONE_LABELS: Record<EventTone, [string, string]> = {
  blue: ["Blue", "Azul"],
  green: ["Green", "Verde"],
  amber: ["Amber", "Âmbar"],
  orange: ["Orange", "Laranja"],
  red: ["Red", "Vermelho"],
  purple: ["Purple", "Roxo"],
  gray: ["Gray", "Cinza"],
}

const HHMM = /^\d{2}:\d{2}$/

function schema(strings: ScheduleStrings) {
  return z
    .object({
      title: z.string().trim().min(1, strings.titleRequired).max(120),
      date: z.date(),
      allDay: z.boolean(),
      time: z.object({
        from: z.string().regex(HHMM).optional(),
        to: z.string().regex(HHMM).optional(),
      }),
      timeZone: z.string().min(1),
      tone: z.enum([
        "blue",
        "green",
        "amber",
        "orange",
        "red",
        "purple",
        "gray",
      ]),
      location: z.string().trim().max(120),
      description: z.string().trim().max(1000),
    })
    .refine(
      (v) => v.allDay || (v.time.from && v.time.to && v.time.to > v.time.from),
      { path: ["time"], message: strings.timeAfter }
    )
}

function at(day: Date, time: string) {
  const [h, m] = time.split(":").map(Number)
  const d = startOfDay(day)
  d.setHours(h, m)
  return d
}

export function EventDialog({
  start,
  onClose,
  onCreate,
  locale,
  weekStartsOn,
  strings,
  timeZone,
}: {
  /** The slot the dialog opens on; `null` keeps it closed. */
  start: Date | null
  onClose: () => void
  onCreate: (event: ScheduleEvent) => void
  locale: Locale
  weekStartsOn?: Day
  strings: ScheduleStrings
  /** Default time zone; "UTC" keeps server and client markup equal. */
  timeZone: string
}) {
  return (
    <Dialog open={start !== null} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="max-h-[calc(100dvh-2rem)] overflow-y-auto sm:max-w-md">
        <DialogHeader>
          <DialogTitle>{strings.dialogTitle}</DialogTitle>
          <DialogDescription>{strings.dialogDescription}</DialogDescription>
        </DialogHeader>
        {start && (
          <EventForm
            // A fresh form per slot.
            key={start.getTime()}
            start={start}
            onClose={onClose}
            onCreate={onCreate}
            locale={locale}
            weekStartsOn={weekStartsOn}
            strings={strings}
            timeZone={timeZone}
          />
        )}
      </DialogContent>
    </Dialog>
  )
}

function EventForm({
  start,
  onClose,
  onCreate,
  locale,
  weekStartsOn,
  strings,
  timeZone,
}: {
  start: Date
  onClose: () => void
  onCreate: (event: ScheduleEvent) => void
  locale: Locale
  weekStartsOn?: Day
  strings: ScheduleStrings
  timeZone: string
}) {
  const pt = locale.code?.startsWith("pt")
  const form = useZodForm(schema(strings), {
    defaultValues: {
      title: "",
      date: startOfDay(start),
      allDay: false,
      time: {
        from: format(start, "HH:mm"),
        to: format(
          start.getHours() >= 23 ? at(start, "23:59") : addMinutes(start, 60),
          "HH:mm"
        ),
      },
      timeZone,
      tone: "blue",
      location: "",
      description: "",
    },
  })
  const allDay = form.watch("allDay")

  return (
    <Form
      form={form}
      className="gap-4"
      onSubmit={(v) => {
        onCreate({
          id: `new-${Math.random().toString(36).slice(2, 9)}`,
          title: v.title,
          allDay: v.allDay,
          start: v.allDay ? startOfDay(v.date) : at(v.date, v.time.from!),
          end: v.allDay ? startOfDay(v.date) : at(v.date, v.time.to!),
          tone: v.tone,
          location: v.location || undefined,
          description: v.description || undefined,
          timeZone: v.timeZone,
        })
        onClose()
      }}
    >
      <FormBanner />
      <FormField
        name="title"
        label={strings.title}
        required
        render={(field) => (
          <Input autoComplete="off" maxLength={120} {...field} />
        )}
      />
      <div className="grid gap-4 sm:grid-cols-2">
        <FormField
          name="date"
          label={strings.date}
          render={(field) => (
            <DatePicker
              id={field.id}
              value={field.value}
              onValueChange={(d) => d && field.onChange(d)}
              onBlur={field.onBlur}
              calendarProps={{ locale, weekStartsOn }}
            />
          )}
        />
        <FormField
          name="allDay"
          label={strings.allDayToggle}
          render={(field) => (
            <div className="flex h-control items-center">
              <Switch
                id={field.id}
                checked={field.value}
                onCheckedChange={field.onChange}
              />
            </div>
          )}
        />
      </div>
      {!allDay && (
        <FormField
          name="time"
          label={strings.time}
          render={(field) => (
            <TimeRangeInput
              id={field.id}
              value={field.value}
              onValueChange={field.onChange}
              interval={15}
            />
          )}
        />
      )}
      <FormField
        name="timeZone"
        label={strings.zone}
        render={(field) => (
          <TimezoneSelect
            id={field.id}
            value={field.value}
            onValueChange={(v) => v && field.onChange(v)}
          />
        )}
      />
      <FormField
        name="tone"
        label={strings.color}
        hideError
        render={(field) => (
          <SwatchPicker
            aria-label={strings.color}
            value={field.value}
            onValueChange={field.onChange}
            swatches={TONES.map((t) => ({
              value: t,
              label: TONE_LABELS[t][pt ? 1 : 0],
              color: `var(--ds-tone-${t})`,
            }))}
          />
        )}
      />
      <FormField
        name="location"
        label={strings.location}
        render={(field) => <Input autoComplete="off" {...field} />}
      />
      <FormField
        name="description"
        label={strings.notes}
        render={(field) => <Textarea rows={3} {...field} />}
      />
      <DialogFooter className="mt-1">
        <DialogClose render={<Button variant="outline" type="button" />}>
          {strings.cancel}
        </DialogClose>
        <FormSubmit>{strings.save}</FormSubmit>
      </DialogFooter>
    </Form>
  )
}

"use client"

import * as React from "react"
import { cn } from "cn"
import {
  addDays,
  addMonths,
  addWeeks,
  format,
  type Day,
  type Locale,
} from "date-fns"
import {
  ChevronDownIcon,
  ChevronLeftIcon,
  ChevronRightIcon,
  MapPinIcon,
  PlusIcon,
  Trash2Icon,
} from "lucide-react"

import { Button } from "@/components/ui/button"
import { Calendar } from "@/components/ui/calendar"
import {
  Popover,
  PopoverContent,
  PopoverDescription,
  PopoverHeader,
  PopoverTitle,
  PopoverTrigger,
} from "@/components/ui/popover"
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs"
import {
  SCHEDULE_VIEWS,
  TONE_VAR,
  monthDayPattern,
  monthWeeks,
  weekDays,
  type ScheduleEvent,
  type ScheduleStrings,
  type ScheduleView,
} from "./schedule-utils"
import {
  Agenda,
  MonthGrid,
  TimeGrid,
  describeWhen,
  formatTime,
  type ViewContext,
} from "./schedule-views"

export type Overlay = { anchor: HTMLElement } & (
  | { kind: "event"; event: ScheduleEvent }
  | { kind: "more"; events: ScheduleEvent[]; title: string }
)

/** The date one step (a day, week or month, per `view`) before or after `date`. */
export function stepDate(view: ScheduleView, date: Date, dir: 1 | -1) {
  if (view === "month") return addMonths(date, dir)
  if (view === "week") return addWeeks(date, dir)
  return addDays(date, dir)
}

/** The days a view shows, the agenda fallback's days, and the header label. */
export function rangeFor(
  view: ScheduleView,
  date: Date,
  locale: Locale,
  weekStartsOn?: Day
) {
  const days =
    view === "week"
      ? weekDays(date, locale, weekStartsOn)
      : view === "day"
        ? [date]
        : monthWeeks(date, locale, weekStartsOn).flat()
  // Agenda for the narrow fallback: the month's own days only.
  const agendaDays =
    view === "month"
      ? days.filter((d) => d.getMonth() === date.getMonth())
      : days
  const pattern = monthDayPattern(locale)
  const label =
    view === "month"
      ? format(date, "LLLL yyyy", { locale })
      : view === "day"
        ? format(date, "PPPP", { locale })
        : `${format(days[0], pattern, { locale })} – ${format(days[6], `${pattern}, yyyy`, { locale })}`
  return { days, agendaDays, label }
}

export function ScheduleToolbar({
  view,
  date,
  rangeLabel,
  todayActive,
  locale,
  weekStartsOn,
  strings,
  onToday,
  onStep,
  onPickDate,
  onViewChange,
  onNewEvent,
}: {
  view: ScheduleView
  date: Date
  rangeLabel: string
  /** True when `date` is already today, so the Today button is disabled. */
  todayActive: boolean
  locale: Locale
  weekStartsOn?: Day
  strings: ScheduleStrings
  onToday: () => void
  onStep: (dir: 1 | -1) => void
  onPickDate: (date: Date) => void
  onViewChange: (view: string) => void
  onNewEvent: () => void
}) {
  const [calendarOpen, setCalendarOpen] = React.useState(false)
  const labels: Record<ScheduleView, string> = {
    month: strings.month,
    week: strings.week,
    day: strings.day,
  }
  return (
    <div className="flex flex-wrap items-center gap-2">
      <Button
        variant="outline"
        size="sm"
        onClick={onToday}
        disabled={todayActive}
      >
        {strings.today}
      </Button>
      <div className="flex items-center">
        <Button
          variant="ghost"
          size="icon-sm"
          aria-label={strings.previous}
          onClick={() => onStep(-1)}
        >
          <ChevronLeftIcon className="rtl:rotate-180" />
        </Button>
        <Button
          variant="ghost"
          size="icon-sm"
          aria-label={strings.next}
          onClick={() => onStep(1)}
        >
          <ChevronRightIcon className="rtl:rotate-180" />
        </Button>
      </div>
      <Popover open={calendarOpen} onOpenChange={setCalendarOpen}>
        <h2 className="min-w-0 text-base font-semibold first-letter:uppercase">
          <PopoverTrigger
            render={
              <Button
                variant="ghost"
                size="sm"
                className="group max-w-full min-w-0 justify-start"
                aria-label={`${rangeLabel}. ${strings.pickDate}`}
              />
            }
          >
            <span className="truncate">{rangeLabel}</span>
            <ChevronDownIcon
              data-icon="inline-end"
              className="transition-transform duration-(--ds-duration-popover) group-data-popup-open:rotate-180"
            />
          </PopoverTrigger>
        </h2>
        <PopoverContent align="start" className="w-auto p-0 max-sm:p-2">
          <Calendar
            mode="single"
            selected={date}
            defaultMonth={date}
            locale={locale}
            weekStartsOn={weekStartsOn ?? locale.options?.weekStartsOn}
            className="mx-auto"
            onSelect={(d) => {
              if (!d) return
              onPickDate(d)
              setCalendarOpen(false)
            }}
          />
        </PopoverContent>
      </Popover>
      <div className="ms-auto flex items-center gap-2">
        <Tabs value={view} onValueChange={(v) => onViewChange(String(v))}>
          <TabsList variant="segmented" aria-label={strings.views}>
            {SCHEDULE_VIEWS.map((v) => (
              <TabsTrigger key={v} value={v}>
                {labels[v]}
              </TabsTrigger>
            ))}
          </TabsList>
        </Tabs>
        <Button size="sm" onClick={onNewEvent}>
          <PlusIcon data-icon="inline-start" />
          <span className="max-sm:sr-only">{strings.newEvent}</span>
        </Button>
      </div>
    </div>
  )
}

/** The day grid, or (week and month) the grid wide and the agenda narrow. */
export function ScheduleBody({
  view,
  date,
  days,
  agendaDays,
  events,
  ctx,
  onEmptyCreate,
}: {
  view: ScheduleView
  date: Date
  days: Date[]
  agendaDays: Date[]
  events: ScheduleEvent[]
  ctx: ViewContext
  onEmptyCreate: () => void
}) {
  if (view === "day") return <TimeGrid days={days} events={events} ctx={ctx} />
  return (
    <>
      <div className="hidden min-h-0 flex-1 flex-col @2xl/schedule:flex">
        {view === "week" ? (
          <TimeGrid days={days} events={events} ctx={ctx} />
        ) : (
          <MonthGrid date={date} events={events} ctx={ctx} />
        )}
      </div>
      <div className="flex min-h-0 flex-1 flex-col @2xl/schedule:hidden">
        <Agenda
          days={agendaDays}
          events={events}
          ctx={ctx}
          onEmptyCreate={onEmptyCreate}
        />
      </div>
    </>
  )
}

/** The popover for one event, or for the events a "+N more" cell hides. */
export function EventOverlay({
  overlay,
  returnFocus,
  locale,
  strings,
  onClose,
  onPick,
  onDelete,
}: {
  overlay: Overlay | null
  returnFocus: React.RefObject<HTMLElement | null>
  locale: Locale
  strings: ScheduleStrings
  onClose: () => void
  onPick: (overlay: Overlay) => void
  onDelete: (event: ScheduleEvent) => void
}) {
  const detail = overlay?.kind === "event" ? overlay.event : null
  return (
    <Popover
      open={overlay !== null}
      onOpenChange={(open) => !open && onClose()}
    >
      <PopoverContent
        anchor={overlay?.anchor}
        align="start"
        className="w-80 max-w-[calc(100vw-1rem)] gap-3"
        finalFocus={returnFocus}
      >
        {detail && (
          <>
            <PopoverHeader
              className={cn("gap-1", TONE_VAR[detail.tone ?? "blue"])}
            >
              <PopoverTitle className="flex items-start gap-2 text-base leading-snug">
                <span
                  aria-hidden
                  className="mt-1.5 size-2.5 shrink-0 rounded-full bg-(--tone)"
                />
                <span className="line-clamp-4 min-w-0">{detail.title}</span>
              </PopoverTitle>
              <PopoverDescription className="ps-[1.125rem] tabular-nums">
                {describeWhen(detail, { locale, strings })}
                {detail.timeZone && !detail.allDay && (
                  <span className="block truncate text-xs">
                    {detail.timeZone.replaceAll("_", " ")}
                  </span>
                )}
              </PopoverDescription>
            </PopoverHeader>
            {detail.location && (
              <p className="flex items-start gap-2 text-muted-foreground">
                <MapPinIcon className="mt-0.5 size-4 shrink-0" aria-hidden />
                <span className="min-w-0">{detail.location}</span>
              </p>
            )}
            {detail.description && (
              <p className="line-clamp-6 text-pretty">{detail.description}</p>
            )}
            <Button
              variant="outline"
              size="sm"
              className="self-start text-destructive"
              onClick={() => onDelete(detail)}
            >
              <Trash2Icon data-icon="inline-start" />
              {strings.delete}
            </Button>
          </>
        )}
        {overlay?.kind === "more" && (
          <>
            <PopoverHeader>
              <PopoverTitle>{overlay.title}</PopoverTitle>
              <PopoverDescription>
                {strings.eventsOverlap(overlay.events.length)}
              </PopoverDescription>
            </PopoverHeader>
            <ul className="-mx-1 flex max-h-72 flex-col gap-0.5 overflow-y-auto">
              {overlay.events.map((event) => (
                <li key={event.id}>
                  <button
                    type="button"
                    onClick={() =>
                      onPick({
                        kind: "event",
                        event,
                        anchor: overlay.anchor,
                      })
                    }
                    className={cn(
                      "flex min-h-9 w-full min-w-0 items-center gap-2 rounded-md px-2 py-1 text-start focus-ring hover:bg-muted",
                      TONE_VAR[event.tone ?? "blue"]
                    )}
                  >
                    <span
                      aria-hidden
                      className="size-2 shrink-0 rounded-full bg-(--tone)"
                    />
                    <span className="min-w-0 flex-1 truncate">
                      {event.title}
                    </span>
                    <span className="shrink-0 text-xs text-muted-foreground tabular-nums">
                      {event.allDay
                        ? strings.allDay
                        : formatTime(event.start, locale)}
                    </span>
                  </button>
                </li>
              ))}
            </ul>
          </>
        )}
      </PopoverContent>
    </Popover>
  )
}

import { addDays, startOfDay } from "date-fns"

import type { ScheduleEvent } from "./schedule-utils"

/** A believable fortnight around `now`, so a demo and a first install both look lived in. */
export function createSampleEvents(now: Date): ScheduleEvent[] {
  const day = (offset: number, h = 0, m = 0) => {
    const d = addDays(startOfDay(now), offset)
    d.setHours(h, m)
    return d
  }
  const timed = (
    id: string,
    title: string,
    offset: number,
    from: [number, number],
    to: [number, number],
    extra: Partial<ScheduleEvent> = {}
  ): ScheduleEvent => ({
    id,
    title,
    start: day(offset, ...from),
    end: day(offset, ...to),
    tone: "blue",
    ...extra,
  })
  return [
    timed("s1", "Daily with the platform team", 0, [9, 30], [9, 45], {
      tone: "green",
      location: "Meet",
    }),
    timed("s2", "Design review: calendar block", 0, [10, 0], [11, 0], {
      tone: "purple",
      location: "Room Ibirapuera",
      description:
        "Walk through week, day and month; decide what ships in the first cut.",
    }),
    timed("s3", "1:1 with Ana Souza", 0, [10, 30], [11, 30], { tone: "amber" }),
    timed("s4", "Lunch with João Silva", 0, [12, 30], [14, 0], {
      tone: "orange",
      location: "Mercado Pinheiros",
    }),
    timed("s5", "Release train", 0, [16, 0], [17, 30], { tone: "red" }),
    timed("s6", "Planning", 1, [9, 0], [10, 30], { tone: "blue" }),
    timed("s7", "Pairing: registry build", 1, [14, 0], [15, 0], {
      tone: "green",
    }),
    timed("s8", "Yoga", -1, [7, 0], [8, 0], { tone: "gray" }),
    timed("s9", "Customer call: Pedro Santos", -1, [15, 0], [16, 0], {
      tone: "blue",
    }),
    timed("s10", "Retro", -2, [11, 0], [12, 0], { tone: "purple" }),
    timed("s11", "Dentist", 3, [8, 30], [9, 15], { tone: "amber" }),
    timed("s12", "Demo day", 4, [15, 0], [16, 30], {
      tone: "red",
      location: "Auditorium",
    }),
    timed("s13", "Maria Oliveira's birthday dinner", 5, [19, 30], [22, 0], {
      tone: "orange",
    }),
    timed("s14", "Rehearsal", 8, [18, 0], [19, 0], { tone: "gray" }),
    timed("s15", "Quarterly review", 9, [13, 0], [15, 0], { tone: "blue" }),
    {
      id: "a1",
      title: "Sprint 42",
      start: day(-2),
      end: day(2),
      allDay: true,
      tone: "green",
    },
    {
      id: "a2",
      title: "Lucas Costa on vacation",
      start: day(3),
      end: day(5),
      allDay: true,
      tone: "amber",
    },
    {
      id: "a3",
      title: "Public holiday",
      start: day(1),
      end: day(1),
      allDay: true,
      tone: "red",
    },
    {
      id: "m1",
      title: "Offsite in Campinas",
      start: day(6, 9, 0),
      end: day(7, 18, 0),
      tone: "purple",
      location: "Campinas, SP",
    },
  ]
}

import {
  addDays,
  differenceInCalendarDays,
  endOfMonth,
  endOfWeek,
  format,
  isValid,
  parse,
  startOfDay,
  startOfMonth,
  startOfWeek,
  type Day,
  type Locale,
} from "date-fns"

export type ScheduleView = "month" | "week" | "day"
export const SCHEDULE_VIEWS: ScheduleView[] = ["month", "week", "day"]

export type EventTone =
  "blue" | "green" | "amber" | "orange" | "red" | "purple" | "gray"

export type ScheduleEvent = {
  id: string
  title: string
  /** Timed events: an instant. All-day events: any time on the first day. */
  start: Date
  /** Timed events: an exclusive instant. All-day events: any time on the last day (inclusive). */
  end: Date
  allDay?: boolean
  tone?: EventTone
  location?: string
  description?: string
  /** IANA id the event was created in; shown in the details. */
  timeZone?: string
}

/** Tone classes, written out so Tailwind can see them. */
export const TONE_CLASS: Record<EventTone, string> = {
  blue: "bg-tone-blue/12 text-tone-blue [--tone:var(--ds-tone-blue)]",
  green: "bg-tone-green/12 text-tone-green [--tone:var(--ds-tone-green)]",
  amber: "bg-tone-amber/12 text-tone-amber [--tone:var(--ds-tone-amber)]",
  orange: "bg-tone-orange/12 text-tone-orange [--tone:var(--ds-tone-orange)]",
  red: "bg-tone-red/12 text-tone-red [--tone:var(--ds-tone-red)]",
  purple: "bg-tone-purple/12 text-tone-purple [--tone:var(--ds-tone-purple)]",
  gray: "bg-tone-gray/12 text-tone-gray [--tone:var(--ds-tone-gray)]",
}

/** Only the `--tone` variable, for markers on a neutral surface. */
export const TONE_VAR: Record<EventTone, string> = {
  blue: "[--tone:var(--ds-tone-blue)]",
  green: "[--tone:var(--ds-tone-green)]",
  amber: "[--tone:var(--ds-tone-amber)]",
  orange: "[--tone:var(--ds-tone-orange)]",
  red: "[--tone:var(--ds-tone-red)]",
  purple: "[--tone:var(--ds-tone-purple)]",
  gray: "[--tone:var(--ds-tone-gray)]",
}

export const TONES = Object.keys(TONE_CLASS) as EventTone[]

export const DATE_PARAM = "yyyy-MM-dd"

export function parseDateParam(value: string | null, ref: Date) {
  if (!value) return null
  const date = parse(value, DATE_PARAM, ref)
  return isValid(date) ? date : null
}

export function weekStart(locale: Locale, override?: Day): Day {
  return override ?? locale.options?.weekStartsOn ?? 0
}

export function weekDays(date: Date, locale: Locale, override?: Day) {
  const start = startOfWeek(date, {
    locale,
    weekStartsOn: weekStart(locale, override),
  })
  return Array.from({ length: 7 }, (_, i) => addDays(start, i))
}

/** Every week of the month as 7 days, padded to whole weeks. */
export function monthWeeks(date: Date, locale: Locale, override?: Day) {
  const opts = { locale, weekStartsOn: weekStart(locale, override) }
  const first = startOfWeek(startOfMonth(date), opts)
  const last = endOfWeek(endOfMonth(date), opts)
  const count = Math.round(differenceInCalendarDays(last, first) / 7) + 1
  return Array.from({ length: count }, (_, w) =>
    Array.from({ length: 7 }, (_, d) => addDays(first, w * 7 + d))
  )
}

/** The last calendar day an event touches (an end at exactly midnight belongs to the day before). */
export function lastDay(event: ScheduleEvent) {
  if (event.allDay) return startOfDay(event.end)
  const end =
    event.end.getTime() > event.start.getTime()
      ? new Date(event.end.getTime() - 1)
      : event.start
  return startOfDay(end)
}

/** All-day and multi-day events live in the all-day row / banner lanes. */
export const isBanner = (event: ScheduleEvent) =>
  event.allDay ||
  differenceInCalendarDays(lastDay(event), startOfDay(event.start)) > 0

export function eventsOnDay(events: ScheduleEvent[], day: Date) {
  const d = startOfDay(day).getTime()
  return events.filter(
    (e) => startOfDay(e.start).getTime() <= d && lastDay(e).getTime() >= d
  )
}

export function eventsInRange(events: ScheduleEvent[], from: Date, to: Date) {
  const a = startOfDay(from).getTime()
  const b = startOfDay(to).getTime()
  return events.filter(
    (e) => startOfDay(e.start).getTime() <= b && lastDay(e).getTime() >= a
  )
}

export const byStart = (a: ScheduleEvent, b: ScheduleEvent) =>
  a.start.getTime() - b.start.getTime() ||
  b.end.getTime() - a.end.getTime() ||
  a.id.localeCompare(b.id)

export type Banner = {
  event: ScheduleEvent
  startIdx: number
  endIdx: number
  lane: number
  /** Began before the first visible day / continues after the last. */
  fromBefore: boolean
  toAfter: boolean
}

/** Lanes for banner events across a run of days (a week row, or the all-day row). */
export function layoutBanners(events: ScheduleEvent[], days: Date[]) {
  const first = startOfDay(days[0])
  const lastIdx = days.length - 1
  const items = events
    .filter(isBanner)
    .map((event) => {
      const s = differenceInCalendarDays(startOfDay(event.start), first)
      const e = differenceInCalendarDays(lastDay(event), first)
      return { event, s, e }
    })
    .filter((x) => x.e >= 0 && x.s <= lastIdx)
    .sort(
      (a, b) =>
        Math.max(a.s, 0) - Math.max(b.s, 0) ||
        b.e - b.s - (a.e - a.s) ||
        a.event.id.localeCompare(b.event.id)
    )
  const laneEnds: number[] = []
  const banners: Banner[] = items.map(({ event, s, e }) => {
    const startIdx = Math.max(s, 0)
    const endIdx = Math.min(e, lastIdx)
    let lane = laneEnds.findIndex((end) => end < startIdx)
    if (lane === -1) lane = laneEnds.length
    laneEnds[lane] = endIdx
    return {
      event,
      startIdx,
      endIdx,
      lane,
      fromBefore: s < 0,
      toAfter: e > lastIdx,
    }
  })
  return { banners, lanes: laneEnds.length }
}

export type Placed = {
  event: ScheduleEvent
  /** Minutes from midnight. */
  top: number
  bottom: number
  col: number
  cols: number
}

export type Overflow = {
  events: ScheduleEvent[]
  top: number
  bottom: number
  col: number
  cols: number
}

const MIN_MINUTES = 20

/**
 * Overlap layout for one day column: events that touch form a cluster; inside
 * it each event takes the first free column and all share the cluster's width.
 * Clusters wider than `cap` columns fold the rest into one "+N" block.
 */
export function layoutDay(events: ScheduleEvent[], day: Date, cap: number) {
  const dayStart = startOfDay(day).getTime()
  const segs = events
    .filter((e) => !isBanner(e))
    .map((event) => {
      const top = Math.max(
        0,
        Math.round((event.start.getTime() - dayStart) / 60000)
      )
      const end = Math.min(
        1440,
        Math.round((event.end.getTime() - dayStart) / 60000)
      )
      return {
        event,
        top,
        bottom: Math.min(1440, Math.max(end, top + MIN_MINUTES)),
      }
    })
    .sort(
      (a, b) =>
        a.top - b.top ||
        b.bottom - b.top - (a.bottom - a.top) ||
        a.event.id.localeCompare(b.event.id)
    )

  const placed: Placed[] = []
  const overflow: Overflow[] = []
  let cluster: typeof segs = []
  let clusterEnd = -1

  const flush = () => {
    if (!cluster.length) return
    const colEnds: number[] = []
    const cols = cluster.map((seg) => {
      let col = colEnds.findIndex((end) => end <= seg.top)
      if (col === -1) col = colEnds.length
      colEnds[col] = seg.bottom
      return col
    })
    const total = colEnds.length
    if (total <= cap) {
      cluster.forEach((seg, i) =>
        placed.push({ ...seg, col: cols[i], cols: total })
      )
    } else {
      const hidden: typeof segs = []
      cluster.forEach((seg, i) => {
        if (cols[i] < cap - 1) placed.push({ ...seg, col: cols[i], cols: cap })
        else hidden.push(seg)
      })
      overflow.push({
        events: hidden.map((h) => h.event),
        top: Math.min(...hidden.map((h) => h.top)),
        bottom: Math.max(...hidden.map((h) => h.bottom)),
        col: cap - 1,
        cols: cap,
      })
    }
    cluster = []
  }

  for (const seg of segs) {
    if (seg.top >= clusterEnd) {
      flush()
      clusterEnd = seg.bottom
    } else clusterEnd = Math.max(clusterEnd, seg.bottom)
    cluster.push(seg)
  }
  flush()
  return { placed, overflow }
}

/** Snaps a pointer offset (0..1 of the day) to the nearest earlier half hour. */
export function slotAt(day: Date, fraction: number) {
  const minutes = Math.min(23.5 * 60, Math.floor((fraction * 1440) / 30) * 30)
  const date = startOfDay(day)
  date.setMinutes(minutes)
  return date
}

