            const first = row.startIdx === index || index === 0
            return (
              <div key={row.event.id} className="-mx-1 flex min-w-0 shrink-0">
                <BannerButton
                  banner={row}
                  ctx={ctx}
                  className={cn(
                    "pointer-events-auto w-full",
                    row.startIdx !== index && "rounded-s-none",
                    row.endIdx !== index && "rounded-e-none",
                    !first && "text-transparent"
                  )}
                />
              </div>
            )
          }
          return (
            <button
              key={row.id}
              type="button"
              title={row.title}
              onClick={(e) => ctx.onSelect(row, e.currentTarget)}
              className={cn(
                "pointer-events-auto flex h-6 min-w-0 shrink-0 items-center gap-1 rounded px-1 text-start text-xs focus-ring hover:bg-muted",
                toneVar(row)
              )}
            >
              <span
                aria-hidden
                className="size-1.5 shrink-0 rounded-full bg-(--tone)"
              />
              <span className="min-w-0 truncate text-foreground">
                <span className="text-muted-foreground tabular-nums">
                  {formatTime(row.start, locale)}
                </span>{" "}
                {row.title}
              </span>
            </button>
          )
        })}
        {hidden > 0 && (
          <button
            type="button"
            onClick={(e) => ctx.onMore(all, e.currentTarget, title)}
            aria-label={`${strings.more(hidden)}, ${title}`}
            className="pointer-events-auto flex h-6 shrink-0 items-center rounded px-1 text-start text-xs font-medium text-muted-foreground focus-ring hover:bg-muted hover:text-foreground"
          >
            {strings.more(hidden)}
          </button>
        )}
      </div>
    </div>
  )
}

export function MonthGrid({
  date,
  events,
  ctx,
}: {
  date: Date
  events: ScheduleEvent[]
  ctx: ViewContext
}) {
  const weeks = monthWeeks(date, ctx.locale, ctx.weekStartsOn)
  const inMonth = eventsInRange(events, weeks[0][0], weeks[weeks.length - 1][6])
  const header = weeks[0]
  return (
    <div
      data-slot="schedule-month"
      className="relative flex min-h-0 flex-1 flex-col overflow-auto overscroll-contain rounded-xl bg-card shadow-border"
    >
      <div
        role="grid"
        aria-label={format(date, "LLLL yyyy", { locale: ctx.locale })}
        className="flex flex-col"
      >
        <div
          role="row"
          className="sticky top-0 z-10 grid grid-cols-7 border-b border-border bg-card"
        >
          {header.map((d) => (
            <div
              key={d.getTime()}
              role="columnheader"
              className="truncate px-2 py-2 text-center text-xs font-medium text-muted-foreground uppercase"
            >
              {format(d, "EEE", { locale: ctx.locale })}
            </div>
          ))}
        </div>
        {weeks.map((week) => {
          const weekEvents = eventsInRange(inMonth, week[0], week[6])
          const { banners, lanes } = layoutBanners(weekEvents, week)
          return (
            <div
              key={week[0].getTime()}
              role="row"
              className="grid grid-cols-7 gap-px border-b border-border bg-border last:border-b-0"
            >
              {week.map((day, i) => (
                <MonthCell
                  key={day.getTime()}
                  day={day}
                  month={date}
                  index={i}
                  banners={banners}
                  lanes={lanes}
                  timed={eventsOnDay(weekEvents, day)
                    .filter((e) => !isBanner(e))
                    .sort(byStart)}
                  ctx={ctx}
                />
              ))}
            </div>
          )
        })}
      </div>
      {!eventsInRange(events, startOfMonth(date), endOfMonth(date)).length && (
        <p className="pointer-events-none absolute inset-x-0 top-1/2 mx-auto w-fit max-w-[80%] -translate-y-1/2 rounded-full bg-popover px-4 py-2 text-center text-sm text-muted-foreground shadow-popover">
          {ctx.strings.nothingHere}
        </p>
      )}
    </div>
  )
}

// ---- Agenda (narrow containers) -----------------------------------------

export function Agenda({
  days,
  events,
  ctx,
  onEmptyCreate,
}: {
  days: Date[]
  events: ScheduleEvent[]
  ctx: ViewContext
  onEmptyCreate: () => void
}) {
  const { locale, strings } = ctx
  const groups = days
    .map((day) => ({
      day,
      items: eventsOnDay(events, day).sort(
        (a, b) => Number(!!isBanner(b)) - Number(!!isBanner(a)) || byStart(a, b)
      ),
    }))
    .filter((g) => g.items.length)

  if (!groups.length)
    return (
      <div className="flex min-h-0 flex-1 rounded-xl bg-card shadow-border">
        <Empty>
          <EmptyHeader>
            <EmptyTitle>{strings.noEvents}</EmptyTitle>
            <EmptyDescription>{strings.nothingHere}</EmptyDescription>
          </EmptyHeader>
          <EmptyContent>
            <Button variant="outline" onClick={onEmptyCreate}>
              {strings.newEvent}
            </Button>
          </EmptyContent>
        </Empty>
      </div>
    )

  return (
    <div
      data-slot="schedule-agenda"
      className="min-h-0 flex-1 overflow-auto overscroll-contain rounded-xl bg-card shadow-border"
    >
      {groups.map(({ day, items }) => {
        const today = isSameDay(day, ctx.now)
        return (
          <section
            key={day.getTime()}
            aria-label={format(day, "PPPP", { locale })}
            className="border-b border-border last:border-b-0"
          >
            <h3
              className={cn(
                "sticky top-0 z-10 flex items-center gap-2 bg-card/95 px-4 py-2 text-xs font-medium text-muted-foreground uppercase backdrop-blur-sm",
                today && "text-foreground"
              )}
            >
              <span className="truncate">
                {format(day, "EEEE, PP", { locale })}
              </span>
              {today && (
                <span className="rounded-full bg-primary px-2 py-0.5 text-[0.6875rem] text-primary-foreground normal-case">
                  {strings.today}
                </span>
              )}
            </h3>
            <ul className="flex flex-col px-2 pb-2">
              {items.map((event) => {
                const banner = isBanner(event)
                const cont = !isSameDay(event.start, day)
                return (
                  <li key={event.id}>
                    <button
                      type="button"
                      onClick={(e) => ctx.onSelect(event, e.currentTarget)}
                      className={cn(
                        "flex min-h-11 w-full min-w-0 items-stretch gap-3 rounded-lg px-2 py-1.5 text-start focus-ring hover:bg-muted",
                        toneVar(event)
                      )}
                    >
                      <span className="w-14 shrink-0 pt-0.5 text-xs text-muted-foreground tabular-nums">
                        {banner || cont ? (
                          cont && !event.allDay ? (
                            strings.continues
                          ) : (
                            strings.allDay
                          )
                        ) : (
                          <>
                            {formatTime(event.start, locale)}
                            <br />
                            {formatTime(event.end, locale)}
                          </>
                        )}
                      </span>
                      <span
                        aria-hidden
                        className="w-0.5 shrink-0 rounded-full bg-(--tone)"
                      />
                      <span className="min-w-0 flex-1">
                        <span className="line-clamp-2 text-sm font-medium text-foreground">
                          {event.title}
                        </span>
                        {event.location && (
                          <span className="block truncate text-xs text-muted-foreground">
                            {event.location}
                          </span>
                        )}
                      </span>
                    </button>
                  </li>
                )
              })}
            </ul>
          </section>
        )
      })}
    </div>
  )
}

export { weekDays }

"use client"

import * as React from "react"
import { cn } from "cn"
import { format, isSameDay, startOfDay, type Day, type Locale } from "date-fns"
import { enUS } from "date-fns/locale"

import { Skeleton } from "@/components/ui/skeleton"
import { toastUndo } from "@/components/ui/sonner"
import { setSearchParams, useSearchParams } from "@/hooks/use-url-state"
import { EventDialog } from "./schedule-event-dialog"
import {
  EventOverlay,
  ScheduleBody,
  ScheduleToolbar,
  rangeFor,
  stepDate,
  type Overlay,
} from "./schedule-parts"
import {
  DATE_PARAM,
  SCHEDULE_VIEWS,
  eventsInRange,
  parseDateParam,
  stringsFor,
  type ScheduleEvent,
  type ScheduleStrings,
  type ScheduleView,
} from "./schedule-utils"
import type { ViewContext } from "./schedule-views"

export type { ScheduleEvent, ScheduleView } from "./schedule-utils"

// The clock ticks once a minute. The server snapshot is 0, so the first client
// render matches the server; `now` can also be pinned (demos, tests).
const subscribeClock = (onChange: () => void) => {
  const id = setInterval(onChange, 60_000)
  return () => clearInterval(id)
}
const minute = () => Math.floor(Date.now() / 60_000) * 60_000
const serverMinute = () => 0

/**
 * Month, week and day calendar. The view (`?view=`) and the date (`?date=`)
 * live in the URL. Week and month fall back to an agenda list when the block is
 * narrower than 42rem (container query), so a phone gets a list, not a grid.
 * Events are held in state; `onEventsChange` hands the new list to the parent.
 */
export function Schedule({
  events: initialEvents,
  locale = enUS,
  weekStartsOn,
  now: nowProp,
  defaultView = "week",
  timeZone = "America/Sao_Paulo",
  strings: stringsProp,
  onEventsChange,
  className,
}: {
  events: ScheduleEvent[]
  /** A date-fns locale: sets the week start, date and time formats, and the UI language (en, pt). */
  locale?: Locale
  /** Overrides the locale's first day of the week (0 = Sunday). */
  weekStartsOn?: Day
  /** Pin "now" (demos, tests); otherwise the clock starts after mount. */
  now?: Date
  defaultView?: ScheduleView
  /** Time zone preselected in the create dialog. */
  timeZone?: string
  strings?: Partial<ScheduleStrings>
  onEventsChange?: (events: ScheduleEvent[]) => void
  className?: string
}) {
  const tick = React.useSyncExternalStore(subscribeClock, minute, serverMinute)
  const now = nowProp ?? (tick ? new Date(tick) : null)

  const params = useSearchParams()
  const strings = React.useMemo(
    () => ({ ...stringsFor(locale), ...stringsProp }),
    [locale, stringsProp]
  )
  const [items, setItems] = React.useState(initialEvents)
  const [overlay, setOverlay] = React.useState<Overlay | null>(null)
  const [creating, setCreating] = React.useState<Date | null>(null)
  const returnFocus = React.useRef<HTMLElement | null>(null)

  const update = (next: ScheduleEvent[]) => {
    setItems(next)
    onEventsChange?.(next)
  }

  if (!now)
    return (
      <Skeleton
        className={cn("min-h-96 flex-1 rounded-xl", className)}
        aria-hidden
      />
    )

  const viewParam = params.get("view") as ScheduleView | null
  const view =
    viewParam && SCHEDULE_VIEWS.includes(viewParam) ? viewParam : defaultView
  const date = parseDateParam(params.get("date"), now) ?? startOfDay(now)

  const goTo = (next: Date) =>
    setSearchParams(
      { date: isSameDay(next, now) ? null : format(next, DATE_PARAM) },
      "push"
    )
  const step = (dir: 1 | -1) => goTo(stepDate(view, date, dir))

  const {
    days,
    agendaDays,
    label: rangeLabel,
  } = rangeFor(view, date, locale, weekStartsOn)

  const ctx: ViewContext = {
    locale,
    strings,
    weekStartsOn,
    now,
    onSelect: (event, anchor) => {
      returnFocus.current = anchor
      setOverlay({ kind: "event", event, anchor })
    },
    onMore: (list, anchor, title) => {
      returnFocus.current = anchor
      setOverlay({ kind: "more", events: list, title, anchor })
    },
    onCreate: (start) => {
      setOverlay(null)
      setCreating(start)
    },
    onOpenDay: (day) =>
      setSearchParams(
        {
          view: "day",
          date: isSameDay(day, now) ? null : format(day, DATE_PARAM),
        },
        "push"
      ),
  }

  const newEventStart = () => {
    const start = startOfDay(date)
    start.setHours(isSameDay(date, now) ? Math.min(now.getHours() + 1, 22) : 9)
    return start
  }

  const rangeEvents = eventsInRange(items, days[0], days[days.length - 1])

  const remove = (event: ScheduleEvent) => {
    setOverlay(null)
    const before = items
    update(items.filter((e) => e.id !== event.id))
    toastUndo(strings.deleted, { onUndo: () => update(before) })
  }

  return (
    <div
      data-slot="schedule"
      className={cn(
        "@container/schedule flex min-h-0 flex-1 flex-col gap-3",
        className
      )}
    >
      <ScheduleToolbar
        view={view}
        date={date}
        rangeLabel={rangeLabel}
        todayActive={isSameDay(date, now)}
        locale={locale}
        weekStartsOn={weekStartsOn}
        strings={strings}
        onToday={() => goTo(now)}
        onStep={step}
        onPickDate={goTo}
        onViewChange={(v) =>
          setSearchParams({ view: v === defaultView ? null : v }, "push")
        }
        onNewEvent={() => ctx.onCreate(newEventStart())}
      />

      <ScheduleBody
        view={view}
        date={date}
        days={days}
        agendaDays={agendaDays}
        events={rangeEvents}
        ctx={ctx}
        onEmptyCreate={() => ctx.onCreate(newEventStart())}
      />

      <EventOverlay
        overlay={overlay}
        returnFocus={returnFocus}
        locale={locale}
        strings={strings}
        onClose={() => setOverlay(null)}
        onPick={setOverlay}
        onDelete={remove}
      />

      <EventDialog
        start={creating}
        onClose={() => setCreating(null)}
        onCreate={(event) => update([...items, event])}
        locale={locale}
        weekStartsOn={weekStartsOn}
        strings={strings}
        timeZone={timeZone}
      />
    </div>
  )
}
